class Solution {
public:
    string answerString(string word, int numFriends) {
        int n = word.size(), m = n - numFriends, best = 0;
        for (int i = 1; i <= m; i++)
            if (word.compare(best, string::npos, word, i, string::npos) < 0)
                best = i;
        return word.substr(best);
    }
};

